def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Check if we're just replacing characters
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found first difference
            # Check if rest matches (insertion case)
            if len(s_in) < len(s_out):
                # Check if we insert at position i
                if s_in[i:] == s_out[i+1:]:
                    return (s_in[i], s_out[i:i+1], i)
            elif len(s_in) > len(s_out):
                # Check if we delete at position i  
                if s_in[i+1:] == s_out[i:]:
                    return (s_in[i], '', i)
            else:
                # Replace at position i
                return (s_in[i], s_out[i], i)

    # If we reach here, one is prefix of other or identical
    if len(s_in) < len(s_out):
        # Insert at end
        return (s_in[-1] if s_in else '', s_out[len(s_in):], len(s_in)-1 if s_in else 0)
    elif len(s_in) > len(s_out):
        # Delete at end
        return (s_in[len(s_out):], '', len(s_out))
    else:
        # Identical
        return ('', '', -1)

